  assert.equal(montarSaudacao(['node', 'ola.mjs']), 'Olá, mundo!');
});

test('lista vazia não quebra o programa', () => {
  assert.equal(montarSaudacao([]), 'Olá, mundo!');
});

solutionCode:
export function montarSaudacao(args) {
  const nome = args[2];
  if (nome === undefined) {
    return 'Olá, mundo!';
  }
  return `Olá, ${nome}!`;
}
